def a_wei_fixed():
    """为：大树替小鸟遮雨，用清楚的受益关系避开人物持物肢体。"""
    rain = lib.wrap(*(
        lib.P(
            f"M {x} {y} Q {x + 8 * s} {y + 13 * s} {x} {y + 22 * s} "
            f"Q {x - 8 * s} {y + 13 * s} {x} {y} Z",
            fill=lib.WBLUE,
        )
        for x, y, s in (
            (118, 142, 1.0), (160, 226, 0.8), (620, 154, 1.0),
            (665, 238, 0.8), (108, 330, 0.72), (648, 352, 0.72),
        )
    ))
    cloud = lib.wrap(
        lib.E(380, 76, 170, 30, "#dbeef5"),
        lib.C(294, 70, 43, "#dbeef5"),
        lib.C(365, 52, 58, "#dbeef5"),
        lib.C(450, 66, 48, "#dbeef5"),
    )
    trunk = lib.wrap(
        lib.P("M 286 430 Q 307 343 300 252 Q 348 235 387 259 Q 361 344 374 430 Z", fill=lib.WOOD_D),
        lib.P("M 323 324 Q 414 282 534 300 L 530 324 Q 425 316 356 364 Z", fill=lib.WOOD_D),
        lib.P("M 317 414 Q 334 337 329 276 Q 346 270 360 279 Q 341 350 350 414 Z", fill=lib.WOOD),
    )
    canopy = lib.wrap(
        lib.E(334, 218, 186, 96, lib.GREEN),
        lib.C(220, 218, 80, lib.GREEN_L),
        lib.C(286, 160, 89, lib.GREEN),
        lib.C(382, 150, 92, lib.GREEN_L),
        lib.C(470, 205, 86, lib.GREEN),
        lib.C(390, 232, 104, lib.GREEN),
        lib.C(269, 224, 72, lib.GREEN_L, 0.8),
    )
    nest = lib.wrap(
        lib.P("M 454 355 Q 510 382 566 355 Q 554 410 510 412 Q 466 410 454 355 Z", fill=lib.WOOD),
        lib.P("M 466 365 Q 510 389 554 365", stroke=lib.WOOD_D, w=7),
        lib.P("M 476 382 Q 510 399 544 382", stroke=lib.WOOD_D, w=6),
    )
    bird = lib.wrap(
        lib.E(505, 342, 43, 30, lib.YEL),
        lib.C(536, 318, 27, lib.SUN_L),
        lib.P("M 558 318 L 584 327 L 558 336 Z", fill=lib.RED),
        lib.E(493, 345, 22, 15, lib.YEL_D),
        lib.C(543, 313, 4.5, lib.INK),
        lib.C(544.5, 311.5, 1.6, lib.WHITE),
    )
    return lib.wrap(lib.ground(), cloud, rain, trunk, canopy, nest, bird)


_arts_mig['为'] = a_wei_fixed()


def arts():
    return dict(_arts_mig)
